mapper.select:
SELECT uh.user_id, uh.user_nm, uh.client_ip, uh.action, uh.created_at, r.role_name AS roleName FROM tb_user_history uh LEFT JOIN tb_user u ON uh.user_id = u.user_id LEFT JOIN tb_role r ON u.role_id = r.role_id WHERE uh.action = '로그인'
AND uh.user_id LIKE CONCAT('%', #{i_userId}, '%')
AND TRIM(SUBSTRING_INDEX(uh.user_nm, '(', 1)) = #{i_userNm}
AND uh.client_ip LIKE CONCAT('%', #{i_client_ip}, '%')
AND uh.created_at > #{i_s_date}
AND uh.created_at < #{i_e_date}
ORDER BY uh.created_at DESC LIMIT #{pageSize} OFFSET #{offset}

SELECT COUNT(1) FROM tb_user_history uh WHERE uh.action = '로그인'
AND uh.user_id LIKE CONCAT('%', #{i_userId}, '%')
AND TRIM(SUBSTRING_INDEX(uh.user_nm, '(', 1)) = #{i_userNm}
